import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AU everyday-crime stories.
extension FollowUpCases {
    static let batchAU: [CaseTemplate] = [dumpingAgain, scratchAgain, dogAgain, phoneAgain, scamSecond, rentAgain, skateAgain, campusAgain, knifeAgain, housePurseAgain, tireIronThreat, extortionAgain, inspectorGift, clubAgain, payrollAgain, hitmanTexts, boatDwi, stashPhone, gunLockLapse]

    static let dumpingAgain = SmallCases.make(
        key: "story.followup.dumpingAgain",
        category: .property,
        headlines: ["Debris Dumped on Another Property", "Defendant From Pasture Dumping Case Linked by Slip"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a vacant lot, causing damage of $1,900, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} found shingles and drywall dumped on a vacant lot. A slip from {D}'s company was in the pile. {DL} says a crew member dumped it.",
        state: [E(.document, 3, "Slip", "A slip from {D}'s company."), E(.physical, 2, "Debris", "Matching debris.", .search)],
        defense: [E(.statement, 1, "Crew Member", "{DL} says a crew member dumped it.")],
        role: "Property owner",
        exam: [.direct("Tell the jury what you own and how you use it.", "\"I own a vacant lot on the edge of town. I've been holding it for a future building site, and I check on it every week or two.\""), .direct("What did you find on the lot that morning?", "\"A big pile of shingles and torn drywall, spread across the corner nearest the road. It had not been there when I'd driven by two days earlier.\""), .direct("What was in the pile that identified anyone?", "\"A delivery slip from a contractor's company, with {D}'s company name printed at the top. It was stuck between two pieces of drywall.\""), .direct("What damage did the dumping do to the lot?", "\"The debris crushed the new grass seed I had put down, and the nails punctured the drainage fabric. Cleaning it up and repairing the ground came to about $1,900.\""), .direct("How did the debris compare to a job {DL} was working on?", "\"A deputy showed me photos of a jobsite where {D.his} crew had torn out a roof and walls that week. The shingles and drywall looked identical.\""), .direct("Had you ever given anyone permission to dump there?", "\"No one. There's a no dumping sign at the entrance, and I've had to put up a gate since.\""), .cross("Can you say who drove the truck that dumped the load?", "\"No. I wasn't there, and nothing at the lot shows who was driving.\""), .cross("Isn't it true that other contractors use similar slips?", "\"I've seen similar paper on other jobs. I wouldn't claim to know which are identical.\""), .cross("Did you see {DL}'s truck at the lot?", "\"I did not. I only know what the deputies told me.\""), .cross("Did {DL} do any work on your property before?", "\"No. I'd never hired {D.him} and never met {D.him} until after this happened.\""), .cross("Was anything else in the pile that could point to someone else?", "\"Not that I saw. It was mostly shingles and drywall, with a few cans and the slip.\"")],
        theory: ("{D} dumped a load of shingles and drywall on a vacant lot, and a slip from {D.his} own company was left in the pile.", "A crew member dumped the load without {DL}'s knowledge, and the slip is a template that several subcontractors use."),
        allocution: "\"A crew member dumped that load on the vacant lot, not me, and I did not know. I'm sorry that the slip from my company was in the pile. I'll clear the lot and pay for what it costs. I'll check where every load goes from now on.\"",
        truths: ("{DL}'s truck was seen on the road near the lot that night, and the debris matches what {DL}'s crew had torn out that week.", "The slip is a shared template used by three subcontractors, and a crew member had the truck keys that night."),
        defendant: [.direct("Did you dump that debris on {V}'s lot?", "\"No, I did not. I never told anybody to haul our debris there, and I wasn't on that road that night.\""), .direct("What was your company doing that week?", "\"We were tearing out a roof and a few walls at a job site about four miles away, and the debris was supposed to go to the county landfill.\""), .direct("Who had your truck that night?", "\"One of my crew members took it home after work because he had an early start. I let my guys do that sometimes.\""), .direct("What do you know about the slip found in the pile?", "\"It's a form that three subcontractors in the county all print from the same template. Mine has my company name, but so do a couple of others.\""), .direct("What did you do when deputies told you about the pile?", "\"I went to the lot and looked at it myself. I told them about my crew member and offered to pay for the cleanup if it turned out to be ours.\""), .direct("Have you asked your crew who did it?", "\"I asked them all. The one who had the truck wouldn't look me in the eye, and I've let him go.\""), .cross("You were in this court before, weren't you?", "\"Yes, I was, and I know that makes it easy to point at me. This time it wasn't my doing.\""), .cross("The slip bears your company name, doesn't it?", "\"The slip does, but it's a template other contractors have. I don't think it's proof I put it there.\""), .cross("Your truck was on that road that night, wasn't it?", "\"It was, but I wasn't driving it. I had loaned it out for the night.\""), .cross("You never reported the missing load to anyone, did you?", "\"No, I didn't. I only found out later that the load was missing.\""), .cross("You can't prove your crew member did it, can you?", "\"Not with a document. I have what he said to me when I asked him.\"")],
        openings: ("{V} found shingles and drywall dumped on a vacant lot, with a slip from {D}'s company lying in the pile. The debris matched a recent job, and {D.he} had already been before this court on {PRIOR}. The State will walk you through the slip and the debris.", "The slip is a template that three subcontractors in this county share, and a crew member had the truck that night. {DL} is accused of an act {D.he} never ordered, and a piece of paper in a pile does not say who drove the truck."),
        closings: ("A slip from {D}'s company lay in the pile, the debris matched {D.his} jobsite, and {DL}'s truck was on that road. This is the second time {D.he} has stood here since {PRIORDATE}.", "The slip is a shared template and the truck was in a crew member's hands. The State has shown trash and paper, not who dumped it. Without that link, the verdict cannot rest on {DL}."),
        timeline: [(-3, "{D}'s crew tears out shingles and drywall at a job site."), (0, "Overnight: a truck dumps the load on the vacant lot."), (1, "{V} finds the pile and the company slip.")],
        identified: "Slip",
        mood: .wantsConviction)

    static let scratchAgain = SmallCases.make(
        key: "story.followup.scratchAgain",
        category: .property,
        headlines: ["Scratch-Off Tickets Taken Again", "Defendant From Lottery Roll Case Back at Counter"],
        law: "larcenyMerchant",
        spec: "Took lottery tickets valued at $200 from {V}, a store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} again pulled a roll of tickets from a dispenser. {DL} says the clerk waved {D.him} on. The loss was put at $200.",
        state: [E(.video, 3, "Counter Camera", "{D} pulls a roll."), E(.physical, 2, "Tickets", "Tickets in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Waved On", "{DL} says the clerk waved {D.him} on.")],
        role: "Store clerk",
        exam: [.direct("Please tell the jury about your job at the store.", "\"I'm a clerk at a convenience store. I work the register, restock the lottery dispenser, and count the roll inventory at the end of each shift.\""), .direct("What did you notice about the lottery dispenser that day?", "\"At closing count, one roll was missing, which was about $200 worth of instant tickets. I checked the register and there was no sale for it.\""), .direct("What does the counter camera show?", "\"It shows {D} at the counter pulling a full roll from the dispenser and walking toward the door. No one else touches the roll.\""), .direct("Where were you when that happened?", "\"I was behind the counter for part of it, and I took a phone call right around then. I remember the phone ringing.\""), .direct("What did you do after you saw the roll was missing?", "\"I told my manager, pulled the camera footage and gave it to the deputies. They found the tickets in a car belonging to {DL}.\""), .direct("How are the tickets supposed to be sold?", "\"The customer asks for them, the clerk scans the roll and rings it up, and then the roll is handed over. Nothing gets handed over before the scan.\""), .cross("Did you speak to {DL} at the counter?", "\"I may have said something, but I don't remember exactly. The phone call took my attention.\""), .cross("Does the camera show you gesturing to {DL}?", "\"There's a moment where I move my hand. I can't tell you now what I meant by it.\""), .cross("Did you walk to the back room that day?", "\"Yes, I went to the back to get a receipt roll for the printer, shortly after that call.\""), .cross("Did you ever tell {DL} not to take the tickets?", "\"I don't recall telling {D.him} anything of the kind.\""), .cross("Has {DL} bought tickets at your store before?", "\"Yes, several times. {D.He} is a regular customer, and I'd never had a problem.\"")],
        theory: ("{D} pulled a full roll of lottery tickets from a dispenser and took it without paying.", "The clerk waved {D.him} on and said {D.he} would ring up the roll later, so {DL} thought it was paid for."),
        allocution: "\"The clerk waved me on, and I took the tickets believing that I would pay later. I should have settled up before I left. I'm sorry for the confusion at the store. I'll pay the two hundred dollars.\"",
        truths: ("The clerk was on the phone and never rang up the roll, and the tickets were found in {DL}'s car.", "The clerk said to take the roll and that the sale would be rung up in a moment, then walked to the back."),
        defendant: [.direct("Did you take the roll of tickets from the dispenser?", "\"Yes, I pulled the roll off the dispenser. I did it because the clerk told me to take it and said the sale would be rung up.\""), .direct("What exactly did the clerk say?", "\"The clerk waved me on and said, 'Take it, I'll ring it up.' Then the clerk went toward the back room.\""), .direct("What did you do after that?", "\"I waited a few moments at the counter. When nobody came back, I thought the clerk had forgotten, and I went out to my car.\""), .direct("Why did you have the tickets in your car?", "\"I put them there to keep them safe. I planned to come back after I had made a stop, and I didn't think I'd done anything wrong.\""), .direct("Have you bought tickets at that store before?", "\"Yes, a lot of times. The clerk knows me, and I've always paid for everything I've taken.\""), .direct("How did you learn it was a problem?", "\"The deputies came to my house and asked about a roll. I told them what the clerk said and showed them where the tickets were.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I was here for a different case. I know I have to be careful about everything I do at a store.\""), .cross("You walked out without paying, didn't you?", "\"I did. I thought it was handled, and I know now I should have waited.\""), .cross("The clerk was on the phone when you took the roll, wasn't the clerk?", "\"The clerk had just taken a call. That's why I took the wave to mean go ahead.\""), .cross("Nobody else heard the clerk say that, did they?", "\"No, there was no one else at the counter. It was just the two of us.\""), .cross("You never went back to pay, did you?", "\"I didn't get a chance before the deputies came. I would have paid that evening.\"")],
        openings: ("A roll of instant lottery tickets worth $200 left a store dispenser without a sale being rung up, and the counter camera shows {D} pulling the roll. Deputies found the tickets in {D.his} car, and {DL} was here before on {PRIOR}.", "The camera also shows the clerk looking at {D} and gesturing, then turning away toward the back room. {DL} says the clerk said to take the roll and that the sale would be rung up. That is not taking without paying."),
        closings: ("A roll worth $200 left the dispenser and was never paid for. The camera shows {D} pulling it, and the tickets were in {D.his} car. {DL} had stood in this courtroom in {PRIORDATE}.", "The clerk waved {D} on and said to take the roll. The clerk then went to the back instead of ringing it. {DL} did what the clerk allowed, and that does not make a theft."),
        timeline: [(0, "{D} comes to the counter and pulls the roll from the dispenser."), (0, "The clerk gestures, answers a phone call and walks toward the back."), (0, "{D} leaves and the roll is never rung up.")],
        identified: "Counter Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let dogAgain = SmallCases.make(
        key: "story.followup.dogAgain",
        category: .publicOrder,
        headlines: ["Neighbor's Cat Found Wounded", "Defendant From Dog Case Accused Again"],
        law: "animalCruelty",
        spec: "Maliciously injured an animal belonging to {V} with a pellet rifle, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s cat was found with a pellet wound. A neighbor heard pops from {D}'s yard again. {DL} says {D.he} was shooting at a target.",
        state: [E(.forensic, 3, "Veterinary Report", "A pellet wound."), E(.physical, 2, "Rifle", "An air rifle and pellets.", .search)],
        defense: [E(.statement, 1, "Target", "{DL} says {D.he} was shooting at a target.")],
        role: "Cat owner",
        exam: [.direct("Please tell the jury about your cat.", "\"My cat is a gray tabby who has been with my family for six years. She goes out in the yard during the day and always comes home for dinner.\""), .direct("What happened to the cat that day?", "\"She came home in the evening limping and holding one back leg up. When I looked at it, there was a small hole in the skin with blood around it.\""), .direct("Where did you take her?", "\"To a veterinarian right away. The doctor found a pellet lodged in the muscle and said it was consistent with an air rifle.\""), .direct("What did your neighbor tell you about that afternoon?", "\"A neighbor said she heard popping sounds from {D}'s yard around the time the cat would have been out.\""), .direct("What did the veterinary report say?", "\"It described a pellet wound to the back leg, and the pellet was kept for the deputies. The cat needed surgery and weeks of rest.\""), .direct("How has this affected your family?", "\"My children were heartbroken, and we've kept the cat indoors since. The surgery and care cost us more than we planned.\""), .cross("Did you see anyone shoot at your cat?", "\"No. I only know what the veterinarian found and what my neighbor heard.\""), .cross("Is there a barbed-wire fence near where your cat roams?", "\"There's an old wire fence at the edge of the field behind our yard, and she sometimes goes through it.\""), .cross("Could a fence cause a wound like that?", "\"The vet said this was a pellet, which is different. I can't tell you more than that.\""), .cross("Have you ever had trouble with {DL} before?", "\"We'd had words about noise and the cat in the yard. Nothing like this.\""), .cross("Did you see {DL}'s yard before the deputies did?", "\"No, I have never been in it.\"")],
        theory: ("{D} shot a neighbor's cat with a pellet rifle from {D.his} own yard.", "{DL} was shooting at a paper target and did not hit the cat, which was hurt on a barbed-wire fence."),
        allocution: "\"I was shooting at a target in my yard, and my pellets moved past the fence. I never meant to hurt the neighbor's cat. I'm sorry that it was hurt. I'll pay the vet bill and put up a backstop.\"",
        truths: ("There was no target anywhere in the yard, and a pellet matching {DL}'s rifle was recovered from the cat.", "The cat had been wounded by a barbed-wire fence, and the target {DL} was shooting at hung in a shed."),
        defendant: [.direct("Did you shoot {V}'s cat?", "\"No. I would never shoot at a cat, and I didn't hit anything that day.\""), .direct("What were you doing with the air rifle?", "\"I was shooting at a paper target I hang on a hay bale. I do it a couple of times a month for practice.\""), .direct("Where was the target that afternoon?", "\"It was hung on the back of the shed, and I took it down when I finished. The deputies didn't see it because I'd put it away.\""), .direct("Do you know how the cat was hurt?", "\"I think she got caught on the barbed wire fence at the back of the field. A lot of animals have been cut on it.\""), .direct("Why did your neighbor hear pops?", "\"Because that's what an air rifle sounds like. I wasn't hiding anything, and I shot for about twenty minutes.\""), .direct("What did you tell the deputies?", "\"I told them everything. I showed them the rifle, the pellets, and where I shoot, and I let them search the yard.\""), .cross("You were here in court before, weren't you?", "\"Yes, I was, and I know people hold it against me. I didn't harm that cat.\""), .cross("You do own a pellet rifle, don't you?", "\"Yes, I do, and I keep it legally. It's for target practice only.\""), .cross("The vet found a pellet in the cat, didn't she?", "\"That's what I've been told. I don't know where that pellet came from.\""), .cross("Nobody saw you shooting at a target, did they?", "\"I was alone in my yard. I can't produce a witness.\""), .cross("You were shooting toward {V}'s yard, weren't you?", "\"No. I shoot toward the hay bale at the back of my lot, away from any neighbor.\"")],
        openings: ("A neighbor's cat was found limping with a pellet wound, and a neighbor heard pops coming from {D}'s yard that afternoon. A deputy found an air rifle and pellets there, and {DL} had been here before on {PRIOR}. The State will show the veterinary report and the rifle.", "{DL} was shooting at a paper target, not a cat, and the cat is hurt in a place that a fence could have torn. A pellet rifle in a yard is not proof of who injured an animal."),
        closings: ("The veterinarian found a pellet wound, a neighbor heard pops from {D}'s yard, and the rifle and pellets were there. {DL} was in this court in {PRIORDATE} and had every reason to know better.", "A pellet rifle in a yard and a hurt cat do not add up to proof. {D} was shooting at a target and the cat could have been cut by barbed wire. The State has not matched the wound to the rifle."),
        timeline: [(0, "Afternoon: a neighbor hears pops from {D}'s yard."), (0, "Evening: {V} finds the cat limping with a wound."), (1, "A veterinarian examines the cat and deputies search {D}'s yard.")],
        identified: "Veterinary Report",
        mood: .wantsConviction)

    static let phoneAgain = SmallCases.make(
        key: "story.followup.phoneAgain",
        category: .property,
        headlines: ["Passenger's Phone Taken Again on Bus", "Defendant From Bus Case Filmed Again"],
        law: "misdLarceny",
        spec: "Stole a phone valued at $600 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a passenger lost a phone on a bus. A camera showed {D} lift it. {DL} says it fell. The loss was put at $600.",
        state: [E(.video, 3, "Bus Camera", "{D} lifts the phone."), E(.digital, 3, "Location", "Phone pings at {D}'s stop.")],
        defense: [E(.statement, 1, "Fell", "{DL} says it fell.")],
        role: "Passenger",
        exam: [.direct("Please tell the jury where you were that day.", "\"I was riding the bus home from work. I sat near the back and had my phone in my jacket pocket most of the ride.\""), .direct("When did you realize the phone was gone?", "\"About ten minutes after I got off. I reached for it to text my family, and it wasn't there.\""), .direct("What did you do next?", "\"I used a family member's phone to track mine. It pinged at a stop two miles down the route, and then it showed offline.\""), .direct("What did you learn from the bus company?", "\"They pulled the camera footage and showed me a person picking my phone up off the seat after I left.\""), .direct("How much was the phone worth?", "\"It was about $600, nearly new, with a case and a lot of photos of my kids that I hadn't backed up.\""), .direct("Have you gotten the phone back?", "\"No. It was turned off after that last ping, and no one has brought it to me or to the terminal.\""), .cross("Did you see {DL} pick up your phone?", "\"No. I was already off the bus. I know only what the video shows.\""), .cross("Could the phone have fallen out of your pocket?", "\"It could have. I didn't feel it go, and I might have shifted in my seat.\""), .cross("Did anyone at the terminal tell you a phone was turned in?", "\"No. I called and asked twice, and they had nothing.\""), .cross("Does the video show the driver speak to {DL}?", "\"I'm not sure. I couldn't see the driver's side in the footage.\""), .cross("Do you know {DL}?", "\"No. I'd never seen {D.him} before.\"")],
        theory: ("{D} picked up a phone left on a bus seat and kept it, and then switched it off.", "The phone fell from the passenger's pocket, and the driver handed it to {DL} to take to the terminal."),
        allocution: "\"That phone fell, and I picked it up, and my own battery was dying. I meant to hand it to the driver. I'm sorry that {V} lost sight of it and worried. I'll return it and pay for any damage.\"",
        truths: ("The bus camera shows {D} lift the phone, and the phone was turned off a few minutes later near {D.his} stop.", "The driver told {DL} to carry the phone to the lost-property desk at the terminal, which {DL} intended to do."),
        defendant: [.direct("Did you take {V}'s phone?", "\"I picked up a phone from the seat. I didn't take it to keep it, and I didn't steal it.\""), .direct("Why did you pick it up?", "\"I saw it on the floor of the bus near the back door. The driver said to me, 'Take that to the terminal,' and I said I would.\""), .direct("What did you do with the phone after that?", "\"I put it in my coat and meant to hand it in at the terminal desk when I got there.\""), .direct("Why did the phone go off near your stop?", "\"It died, I think. The battery was low and it shut off before I got to the terminal.\""), .direct("Where is the phone now?", "\"The deputies found it in my coat pocket at home. I'd put my coat on a hook and forgotten about it.\""), .direct("Why didn't you hand it in right away?", "\"I got off at a different stop than I'd planned and got a call about work. I meant to take it the next morning.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know how it sounds. I still did not steal this phone.\""), .cross("You never told anyone you had it, did you?", "\"I didn't. I figured I'd drop it at the desk myself, and I should have called someone.\""), .cross("You turned the phone off, didn't you?", "\"No. It died on its own, as far as I know.\""), .cross("The driver isn't here to confirm what was said, is he?", "\"The driver hasn't testified. I can only tell you what I heard.\""), .cross("You kept the phone overnight, didn't you?", "\"I did. I should have taken it in the same day.\"")],
        openings: ("A passenger lost a $600 phone on a bus, and the bus camera shows {D} lifting it from the seat. The phone's location pinged at {D}'s stop and then went dark, and {D.he} had been here before on {PRIOR}.", "The phone fell from the passenger's pocket, and the driver asked {DL} to carry it to the terminal desk. {DL} took it for that reason and did not mean to keep it."),
        closings: ("The camera shows {D} lifting the phone, the location pinged at {D.his} stop, and then it went dark. {DL} had already been to this court in {PRIORDATE}. Taking a lost phone and shutting it off is stealing.", "The phone fell and the driver told {D} to take it to the terminal. The State shows a hand lifting a phone, not an intent to keep it, and the evidence of intent is missing."),
        timeline: [(0, "The passenger gets off the bus and the phone falls from {V.his} pocket."), (0, "The bus camera shows {D} lift the phone from the seat."), (0, "The phone pings at {D}'s stop and then goes dark.")],
        identified: "Bus Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let scamSecond = SmallCases.make(
        key: "story.followup.scamSecond",
        category: .whiteCollar,
        headlines: ["Second Elderly Victim Wires Money", "Defendant From Wire Scam Collects Again"],
        law: "exploitationElder",
        spec: "Knowingly obtained $1,800 from {V}, an elder, by deception, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a second elderly victim wired $1,800. The wire was collected by {D}. {DL} says it was another package job.",
        state: [E(.document, 3, "Wire Receipt", "$1,800 picked up by {D}."), E(.video, 3, "Camera", "{D} collects cash.")],
        defense: [E(.statement, 1, "Package Job", "{DL} says it was a package job.")],
        role: "Victim",
        exam: [.direct("Please tell the jury how this began.", "\"I got a phone call from someone who said he was a police officer and that my grandson had been in an accident and needed money for bail.\""), .direct("What did you do after the call?", "\"I was scared and wanted to help. I went to a store and wired $1,800 as the caller told me to, and he said someone would pick it up.\""), .direct("When did you learn it was a scam?", "\"That evening, when my grandson called to say hello. He was at home and safe, and nothing had happened to him.\""), .direct("What did you do then?", "\"I called the sheriff's office, and they started tracing the wire. They told me the money had been picked up at a store across town.\""), .direct("What did the wire receipt show?", "\"It showed $1,800 picked up under {D}'s name that same afternoon, with {D.his} identification number.\""), .direct("How has this affected you?", "\"I'm embarrassed, and I'm afraid to answer the phone now. That was money I'd saved for years.\""), .cross("Did you ever speak to {DL} on the phone?", "\"No. The voice on the phone was a man I'd never heard before.\""), .cross("Did you see {DL} pick up the money?", "\"No. I only saw the receipt and the video the deputies showed me.\""), .cross("Did the caller ever mention {DL}'s name?", "\"No, he did not. He said someone would pick it up, and that was all.\""), .cross("Do you know whether {DL} knew where the money came from?", "\"I don't. I can only say what happened to me.\""), .cross("Did you get any of your money back?", "\"No, none of it. The man who called is the one I'd like to see held responsible.\"")],
        theory: ("{D} picked up $1,800 wired by an elderly victim, after a phone scam, as {D.he} had done before.", "{DL} was hired to pick up a package and had no idea the money was from a scam."),
        allocution: "\"I picked up that wire as a package job, and I did not know the money came from an elderly person. I'm sorry that {V} lost eighteen hundred dollars. I'll give the court the name of who hired me, and I'll help get the money back.\"",
        truths: ("{DL} had made five prior pickups for the same caller, and the camera shows {D.him} counting the cash.", "The man who hired {DL} was arrested and told deputies {DL} knew nothing about the scam."),
        defendant: [.direct("Did you pick up the $1,800 wire?", "\"Yes, I did. I was hired to pick up a package, and I didn't know it was money from anyone's scam.\""), .direct("Who hired you?", "\"A man I met through a friend. He paid me a small fee each time I picked up a package at a wire store and brought it to him.\""), .direct("What did you think you were picking up?", "\"Packages for his business. He said it was cash from customers who paid at wire stores, and I never asked more.\""), .direct("Did you speak to {V}?", "\"Never. I didn't know the name or anything about {V.him} until the deputies told me.\""), .direct("What did you do with the money?", "\"I gave it to the man right away, in an envelope. I kept a $50 fee, as we had agreed.\""), .direct("What happened to the man who hired you?", "\"He was arrested, and I understand he told deputies I didn't know anything about it.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and I know that makes this look worse. I'm telling you what I believed.\""), .cross("You had picked up wires for him five times, didn't you?", "\"Yes, about that many. I never asked where the money came from, and I should have.\""), .cross("You were paid for each pickup, weren't you?", "\"I was paid a small fee each time. I thought it was ordinary work.\""), .cross("You used your own ID at the counter, didn't you?", "\"Yes. I didn't hide anything, because I didn't know it was wrong.\""), .cross("You counted the cash on camera, didn't you?", "\"I did, to make sure it matched what the clerk gave me.\"")],
        openings: ("{V}, an elderly victim, got a call saying a relative was in trouble and wired $1,800. The wire was picked up by {D}, the camera shows {D.him} collecting the cash, and {D.he} was here before on {PRIOR}.", "{DL} was hired to pick up a package for a man, and was paid a small fee. {DL} did not make the call, never spoke to {V}, and the man who hired {D.him} has since been arrested and told deputies {DL} knew nothing."),
