        role: "Landlord",
        exam: [.direct("Please tell the jury about your rental business.", "\"I own a few rental units in town. I've been a landlord for about twelve years and I handle the leases, the rent and the repairs myself.\""), .direct("When did {D} rent from you?", "\"{DL} moved into a unit I own after leaving a previous rental. We signed a lease and agreed on the rent and a deposit.\""), .direct("How did {DL} pay the first rent?", "\"With two checks, each for part of the $1,800 that was due. I deposited them the same day.\""), .direct("What happened to the checks?", "\"Both came back from the bank marked account closed. The bank sent me a notice with the dates and fees.\""), .direct("What did you do when they came back?", "\"I called {DL}, who said it must be a bank mistake and promised to fix it. Then I waited a week and filed a report.\""), .direct("What did you lose because of the bad checks?", "\"The rent for the month, plus about $70 in fees from my own bank, and the weeks I spent chasing it.\""), .cross("Did {DL} tell you right away that the bank might have made an error?", "\"Yes, the same day I called. {D.He} sounded surprised.\""), .cross("Did {DL} offer to pay by another method?", "\"{D.He} did say {D.he} would bring a money order once the bank straightened it out.\""), .cross("Did {DL} ever pay you the rent?", "\"Not as of today. That is why I filed a report.\""), .cross("Have you seen the bank's own letters about the account?", "\"I've seen copies the deputies gave me. They say the account was closed.\""), .cross("Was {DL} ever late on rent before these checks?", "\"No, this was the first month.\"")],
