        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a dean received an email saying 'You'll regret this.' It traced to {D}'s apartment network. {DL} says the router is shared.",
        state: [E(.digital, 3, "Email", "'You'll regret this.'"), E(.digital, 3, "Logs", "Account created from {D}'s network.")],
        defense: [E(.statement, 1, "Shared Router", "{DL} says the router is shared.")],
        role: "Dean",
        exam: [.direct("Please tell the jury what you do at the university.", "\"I'm a dean at the university. I oversee student conduct and academic matters, which means I deal with disputes and complaints.\""), .direct("What did you receive that day?", "\"An email with the subject line empty and a single line, 'You'll regret this.' It came from an address I didn't recognize.\""), .direct("Why did the message concern you?", "\"I'd just made a decision in a student matter involving {D}. The message came right after that, so I treated it as a threat.\""), .direct("What did you do after reading it?", "\"I forwarded it to campus security and the sheriff's office, and I changed my parking spot for a few weeks.\""), .direct("What did the investigation show about the account?", "\"The account was created the day before, from an internet address that traced to an apartment where {DL} lives.\""), .direct("How has this affected your work?", "\"I've been more careful, and I asked for a security escort for a while. A threat like that stays with a person.\""), .cross("Did the email name {DL}?", "\"No. It was signed with nothing, and I only know what the logs say.\""), .cross("Did anyone see {DL} send the email?", "\"Not that I know of. It's a trace of an address and nothing more.\""), .cross("Do you know how many people share that apartment's network?", "\"I don't. The deputies would know that better than I do.\""), .cross("Had {DL} ever threatened you before?", "\"No, never. We had a disagreement over a decision.\""), .cross("Is it possible someone else used that network?", "\"I suppose it is. I wouldn't claim to know.\"")],
        theory: ("{D} sent a dean an email saying 'You'll regret this,' and the account was created from {D.his} network.", "A shared router serves the whole apartment complex, and eleven other devices used it that hour."),
        allocution: "\"I did not send that email. The router in my apartment is shared with others. I'm sorry that the dean was frightened. I'd ask the court to look at who else uses that network.\"",
        truths: ("{DL}'s roommates were away that day and the email was sent from the apartment network.", "Eleven other devices used the apartment network in the same hour, and the logs cannot say which one sent the email."),
        defendant: [.direct("Did you send the dean that email?", "\"No, I did not. I didn't create that account and I didn't write that message.\""), .direct("How does your apartment get internet?", "\"Through a shared router that serves the whole building. Anyone who has the password can use it, and a lot of neighbors do.\""), .direct("Where were you when the email was sent?", "\"At work, on my shift, and I got home after dark. I wasn't at the apartment at that time.\""), .direct("Who else lives in your apartment?", "\"Two roommates. They both had their own phones and computers, and one of them had been angry about the decision.\""), .direct("What did you tell the deputies?", "\"I told them it wasn't me and that anybody on the network could have done it. I let them look at my devices.\""), .direct("What did they find on your devices?", "\"Nothing. There was no account like that, and no draft of the message.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'm sorry about that. It doesn't mean I sent this message.\""), .cross("You were upset with the dean, weren't you?", "\"I disagreed with the decision. I never wished the dean harm.\""), .cross("Your roommates were away that day, weren't they?", "\"That's what the deputies say. I don't know where they were.\""), .cross("The logs trace to your apartment's network, don't they?", "\"They do, but eleven other devices were on it that hour.\""), .cross("You can't prove who used the network, can you?", "\"No. It's a shared router, and anybody could have done it.\"")],
