        role: "Victim",
        exam: [.direct("Please tell the jury what you received.", "\"A letter in the mail, with a typed note inside. It said, '$2,000 or everyone knows,' and it told me to leave cash at a certain place.\""), .direct("What did you understand the letter to mean?", "\"That someone had private information about me and would send it to my employer unless I paid. I was frightened it could cost me my job.\""), .direct("What did you do after reading it?", "\"I called the sheriff's office that same day and gave them the letter and the envelope. I did not pay anything.\""), .direct("What was on the envelope?", "\"My name and address in handwriting, with a stamp. A deputy sent it to an examiner.\""), .direct("What did the examiner conclude?", "\"The examiner said the handwriting matched {D}'s known writing. The report is in evidence.\""), .direct("How did the letter affect you?", "\"I stopped sleeping well. I kept wondering who knew what, and whether my employer would be told.\""), .cross("Did you see {DL} send the letter?", "\"No. I only know what the examiner and deputies told me.\""), .cross("Was the letter itself handwritten?", "\"No, it was typed. Only the envelope was handwritten.\""), .cross("Do you know whether the examiner is certain?", "\"The report said a match, but I'm not an expert.\""), .cross("Did you and {DL} have any dispute before?", "\"We'd had a falling out a while back. I wouldn't call it much more.\""), .cross("Have you received any other letters?", "\"No, only this one. I haven't received any other letters.\"")],
        theory: ("{D} mailed {V} a letter demanding $2,000 or private information would be sent to {V.his} employer.", "Someone forged {D.his} handwriting, and the letter was typed on a public library printer."),
