        defendant: [.direct("Did you reroute the pay?", "\"No. I entered what the system had and followed the existing routing. I never moved money to my own accounts.\""), .direct("What problems did you notice in the payroll system?", "\"Duplicate entries and wrong account numbers, mostly. A lot of the old edits looked odd, and I assumed they'd been approved.\""), .direct("Did you tell anyone about the errors?", "\"I told the owner about a few. I should have kept a written list.\""), .direct("How do you explain the accounts the money went to?", "\"I don't know. Some of the old routing entries pointed to accounts I'd never heard of.\""), .direct("Why were your edits in the log?", "\"Because I worked in the system every day. Some were corrections I made to fix wrong amounts.\""), .direct("What did you do when the audit came?", "\"I cooperated and gave the accountant everything I had. I was surprised by the total.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know how that colors things. I did not take this money.\""), .cross("The edits are under your login, aren't they?", "\"Yes, they are. Some were mine, but I was following what the system showed.\""), .cross("The money went to accounts connected to you, didn't it?", "\"That's what I was told. I can't explain it.\""), .cross("You never wrote down your concerns, did you?", "\"No, only conversations. I should have been much more careful than I was.\""), .cross("You began editing in week three, didn't you?", "\"That's about right. I was getting up to speed on the system.\"")],
        openings: ("{D} took a payroll job at a new company, and an audit found $14,000 rerouted to other accounts. The logs show edits under {D}'s login beginning in week three, and {DL} had been in this court before on {PRIOR}.", "The software had errors and carried over edits from the prior payroll clerk. {DL} followed the existing entries, and a mistake in a system that was already wrong is not a theft."),
        closings: ("The audit found $14,000 rerouted and the logs show the edits under {D}'s login starting in week three. {DL} had been here in {PRIORDATE}. The money did not move itself.", "The system had errors and carried over a prior clerk's edits. {D} followed what was there. The State must show {D.he} meant to take the money, and the audit does not say so."),
        timeline: [(-60, "{D} starts the payroll job at the new company."), (-40, "Edits to payroll routing begin under {D}'s login."), (0, "The company audit finds $14,000 rerouted.")],
