    static let hitmanTexts = SmallCases.make(
        key: "story.followup.hitmanTexts",
        category: .violent,
        headlines: ["Spouse Receives Threatening Texts After Plot Case", "Defendant From Murder-for-Hire Case Contacts Victim"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} received texts from a new number: 'Next time I'll do it myself.' It traced to {D}. {DL} says {D.he} never sent them.",
        state: [E(.digital, 3, "Texts", "'Next time I'll do it myself.'"), E(.digital, 3, "Carrier Records", "The number is {D}'s.")],
        defense: [E(.statement, 1, "Not Sent", "{DL} says {D.he} never sent them.")],
        role: "Victim",
        exam: [.direct("Please tell the jury how this began.", "\"I got a text from a number I didn't know, saying, 'Next time I'll do it myself.' It came in the evening, and I had no idea who sent it.\""), .direct("What did you think when you saw it?", "\"I thought of the earlier case and what {D} had said then. I was afraid someone would come to my door.\""), .direct("What did you do?", "\"I took screenshots and called the sheriff's office. I gave them the number and my phone.\""), .direct("What did the carrier records show?", "\"That the number was registered to {DL}. The deputy showed me the page.\""), .direct("How many messages did you receive?", "\"Two that night, with the same wording. There were no others after I reported it.\""), .direct("How did the texts change your routine?", "\"I changed my locks and I stayed with family for a few days. I was on edge every time my phone made a sound.\""), .cross("Did the text name anyone?", "\"No. It was unsigned, so the text named no one.\""), .cross("Did you see {DL} send the messages?", "\"No. I only know the number and what the carrier says.\""), .cross("Do you know whether {DL} had a phone in custody?", "\"I was told {D.he} was in custody. I don't know more than that.\""), .cross("Did you recognize the writing style?", "\"Not really. It could have been anyone.\""), .cross("Were any other threats sent after the deputies were told?", "\"No, that was the end of it.\"")],
        theory: ("{D} sent {V} texts from a new number reading 'Next time I'll do it myself.'", "{DL} never sent the texts, and another inmate used {DL}'s tablet account."),
        allocution: "\"I never sent those texts, and I have no idea who did. A shared phone plan may be how my number was used. I'm sorry that {V} was frightened by words like that. I hope the sender is found.\"",
        truths: ("The phone was in {DL}'s cell, and the carrier records show the number is {D.his}.", "Another inmate used {DL}'s tablet account, and the tablet was shared on the unit."),
        defendant: [.direct("Did you send those texts to {V}?", "\"No, I did not. I never wrote to {V.him}, and I don't know how the texts got sent.\""), .direct("How are phones and tablets handled where you are held?", "\"We use shared tablets, and each person has an account. People trade passwords and sometimes use each other's accounts.\""), .direct("Who used your account?", "\"Another inmate who I'd shared a tablet with. I didn't know he was sending anything until deputies told me.\""), .direct("Why was a phone found in your cell?", "\"It was in a bag of someone else's belongings. I never used it and didn't know it was there.\""), .direct("What did you tell deputies when they asked?", "\"That I never sent a text. I told them who I'd lent the tablet to.\""), .direct("How do you feel about being accused?", "\"Frustrated. I've been in court before, and I'm trying to keep my record clean.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know how that sounds. I didn't write those messages.\""), .cross("The number is registered in your name, isn't it?", "\"It is, but I never gave anyone permission to use it for that.\""), .cross("The phone was in your cell, wasn't it?", "\"It was found there. I didn't know it was in the bag.\""), .cross("You can't prove who used your tablet, can you?", "\"Not with a document. I can only tell you what happened.\""), .cross("You knew {V}'s history with you, didn't you?", "\"Yes, and I'd never wish harm on {V.him}.\"")],
        openings: ("{V} received texts from a new number that read 'Next time I'll do it myself.' Carrier records tie the number to {D}, and the phone was in {D.his} cell. {DL} had been here before on {PRIOR}.", "{DL} did not send the texts, because another inmate used {DL}'s tablet account. A number registered to a name is not proof that the named person was at the keyboard."),
        closings: ("The texts came from a number registered to {D}, and the phone was in {D.his} cell. {DL} had been in this court in {PRIORDATE}. The words 'Next time I'll do it myself' were a threat.", "The tablet was shared and another inmate used {DL}'s account. The records say whose account it is, not who typed. The State has not shown {D} sent a word."),
        timeline: [(0, "{V} receives the first text from an unknown number."), (0, "{V} receives the second text and reports them."), (1, "Carrier records tie the number to {D}.")],
        identified: "Texts",
        mood: .wantsConviction,
        genders: ["D": .male, "V": .female])

    static let boatDwi = SmallCases.make(
        key: "story.followup.boatDwi",
