        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a marine officer stopped {D} on the lake. {DL} blew 0.09. {DL} says the boat was drifting.",
        state: [E(.forensic, 3, "Breath Test", "0.09."), E(.statement, 3, "Marine Officer", "{D} at the wheel.")],
        defense: [E(.statement, 1, "Drifting", "{DL} says the boat was drifting.")],
        role: "Marine patrol officer",
        exam: [.direct("Please tell the jury about your duties.", "\"I'm a marine patrol officer. I patrol the lake, check safety equipment, and respond to complaints about unsafe boating.\""), .direct("What did you see when you approached {D}'s boat?", "\"The boat was moving slowly in a cove, and {DL} was at the wheel. I could smell alcohol as I came alongside.\""), .direct("What did you observe about {DL}?", "\"Red, glassy eyes and slow speech, and {D.he} had trouble finding the registration. {D.He} admitted to a couple of drinks.\""), .direct("What did the breath test show?", "\"A reading of 0.09 on a calibrated device, about forty minutes after I first saw the boat.\""), .direct("Was the motor running?", "\"I heard the motor when I approached, and the boat was turning slowly. I didn't see an anchor line.\""), .direct("What did you do next?", "\"I had a deputy meet us at the ramp. {DL} was arrested, and the boat was secured to the dock.\""), .cross("Was the boat moving through the water?", "\"It was moving slowly. It could have been drifting, and I'm not certain of the speed.\""), .cross("Did you see anyone else on the boat?", "\"There was a friend on board. I didn't ask who was at the wheel before I boarded.\""), .cross("Was the engine in gear?", "\"I couldn't tell. I only know the engine was on.\""), .cross("Did you see an anchor deployed?", "\"I didn't see one, but I wasn't looking for it.\""), .cross("Was the lake crowded?", "\"No, it was a calm afternoon, with few boats near the cove.\"")],
        theory: ("{D} operated a boat on the lake while impaired, with a breath test of 0.09.", "The boat was anchored with the engine off and a sober friend at the helm when the officer arrived."),
